}

install_ipaudio() {
    command -v ffmpeg >/dev/null 2>&1 || opkg install ffmpeg || return 1
    MAJOR=$(ffmpeg -version 2>/dev/null | awk 'NR==1 {split($3,a,"."); print a[1]}')
    case "$MAJOR" in
        7|8)
            remote https://raw.githubusercontent.com/zKhadiri/IPAudioPro-Releases-/main/installer.sh
            return $?
            ;;
        9)
            say 'FFmpeg 9: using upstream FFmpeg 8 build; runtime compatibility not guaranteed'
            ;;
        *)
            say "Unsupported FFmpeg $MAJOR"
            return 1
            ;;
    esac
    PY=$(python3 -c 'import sys; print("%d.%d" % sys.version_info[:2])') || return 1
    case "$PY" in
        3.12) FF=7.1 ;;
        3.13|3.14) FF=8.0 ;;
        *) return 1 ;;
    esac
    case "$(uname -m)" in
        aarch64)
            DIR=aarch64
            ARCH=aarch64
            ;;
        *mips*)
            DIR=mipsel
            ARCH=mips32el
            ;;
        arm*)
            DIR=arm
            ARCH=''
            for A in cortexa15hf-neon-vfpv4 cortexa9hf-neon cortexa7hf-vfp armv7ahf-neon; do
                if opkg print-architecture 2>/dev/null | grep -q " $A " || ls /etc/opkg 2>/dev/null | grep -q "$A"; then
                    ARCH=$A
                    break
                fi
            done
            [ -n "$ARCH" ] || return 1
            ;;
        *)
            return 1
            ;;
    esac
    META=/tmp/apanel-ipaudio-meta-$$.sh
    wget -qO "$META" https://raw.githubusercontent.com/zKhadiri/IPAudioPro-Releases-/main/installer.sh || return 1
    VER=$(sed -n 's/^VERSION=\([0-9][0-9.]*\).*$/\1/p' "$META" | head -n 1)
    rm -f "$META"
    [ -n "$VER" ] || return 1
    PKG="enigma2-plugin-extensions-ipaudiopro_${VER}_${ARCH}_py${PY}_ff${FF}.ipk"
    URL="https://raw.githubusercontent.com/zKhadiri/IPAudioPro-Releases-/main/v${VER}/python${PY}/${DIR}/${PKG}"
    IPK=/tmp/apanel-ipaudio-$$.ipk
    if ! wget -qO "$IPK" "$URL" || [ ! -s "$IPK" ]; then
        rm -f "$IPK"
        return 1
    fi
    opkg install "$IPK"
    RC=$?
    rm -f "$IPK"
    [ "$RC" -eq 0 ] || return "$RC"
    opkg list-installed | grep -q '^enigma2-plugin-extensions-ipaudiopro '
}


# IPAudio Plus upstream installer restarts/kills Enigma2 inside its shell.
# Use its published version/architecture package path directly so A Panel
# controls the sole receiver reboot after its complete installation batch.
install_ipaudioplus() {
    PLUS_BASE=https://raw.githubusercontent.com/Ahmadarjan1/IPAudioPlus-Releases/main
    PLUS_META=/tmp/apanel-ipaudioplus-meta-$$.sh
    PLUS_IPK=/tmp/apanel-ipaudioplus-$$.ipk
    rm -f "$PLUS_META" "$PLUS_IPK"
    if ! wget -qO "$PLUS_META" "$PLUS_BASE/installer.sh" || [ ! -s "$PLUS_META" ]; then
        rm -f "$PLUS_META"
        return 1
    fi
    # Parse data only: never execute a remotely fetched installer in our batch.
    PLUS_VER=$(sed -n 's/^VERSION="\([0-9][0-9.]*\)".*/\1/p' "$PLUS_META" | head -n 1)
    rm -f "$PLUS_META"
    case "$PLUS_VER" in
        ''|*[!0-9.]*|.*|*..*|*.)
            say 'IPAudio Plus: upstream version is missing or invalid.'
            return 1 ;;
    esac
    PLUS_PY=$(python3 -c 'import sys; print("%d.%d" % sys.version_info[:2])') || return 1
    case "$PLUS_PY" in
        3.9|3.11|3.12|3.13|3.14) : ;;
        *) say "IPAudio Plus: unsupported Python $PLUS_PY"; return 1 ;;
    esac
    PLUS_BITS=$(python3 -c 'import struct; print(struct.calcsize("P") * 8)') || return 1
    case "$(uname -m)" in
        aarch64|arm64)
            if [ "$PLUS_BITS" = 32 ]; then PLUS_ARCH=arm; else PLUS_ARCH=aarch64; fi ;;
        arm*) PLUS_ARCH=arm ;;
        mips*) PLUS_ARCH=mipsel ;;
        *) say 'IPAudio Plus: unsupported CPU'; return 1 ;;
    esac
    PLUS_FILE="enigma2-plugin-extensions-ipaudioplus_${PLUS_VER}_${PLUS_ARCH}_py${PLUS_PY}.ipk"
    PLUS_URL="${PLUS_BASE}/v${PLUS_VER}/python${PLUS_PY}/${PLUS_ARCH}/${PLUS_FILE}"
    say "IPAudio Plus: downloading ${PLUS_FILE}"
    if ! wget -qO "$PLUS_IPK" "$PLUS_URL" || [ ! -s "$PLUS_IPK" ]; then
        rm -f "$PLUS_IPK"
        return 1
    fi
    PLUS_MAGIC=$(dd if="$PLUS_IPK" bs=8 count=1 2>/dev/null)
    PLUS_SIZE=$(wc -c < "$PLUS_IPK")
    if [ "$PLUS_MAGIC" != '!<arch>' ] || [ "$PLUS_SIZE" -lt 100000 ]; then
        say 'IPAudio Plus: invalid IPK archive downloaded.'
        rm -f "$PLUS_IPK"
        return 1
    fi
    # Match the published upstream opkg flags, without its GUI restart.
    opkg install --nodeps --force-reinstall --force-overwrite "$PLUS_IPK"
    PLUS_RC=$?
    rm -f "$PLUS_IPK"
    [ "$PLUS_RC" -eq 0 ] || return 1
    if ! pkg_installed enigma2-plugin-extensions-ipaudioplus ||
       [ ! -f /usr/lib/enigma2/python/Plugins/Extensions/IPAudioPlus/plugin.py ]; then
        say 'IPAudio Plus: package did not pass post-install verification.'
        return 2
    fi
    return 0
}

install_levi() {
    URL=https://raw.githubusercontent.com/levi-45/Levi45Emulator/main/enigma2-plugin-softcams-oscam-emu-pcsc-levi45_11968-803_all.ipk
    IPK=/tmp/apanel-levi-$$.ipk
    if ! wget -qO "$IPK" "$URL" || [ ! -s "$IPK" ]; then
        rm -f "$IPK"
        return 1
    fi
    opkg install --force-overwrite "$IPK"
    RC=$?
    rm -f "$IPK"
    say "Levi45 opkg exit status: $RC"
    INSTALLED=$(opkg list-installed | grep -Ei '^enigma2-plugin[^ ]*oscam[^ ]*levi[^ ]* - ' | head -n 1)
    if [ -n "$INSTALLED" ]; then
        [ "$RC" -eq 0 ] && return 0
        return 2
    fi
    [ -x /usr/bin/OSCam_11968-803 ] && return 2
    return 1
}

