# Cam packages supplied with A Panel have postrm scripts that use broad globs.
# Fail closed if a different package/postrm is installed. The original
# removal script is backed up and replaced ONLY for the opkg transaction.
# No generic /etc/tuxbox/config, /usr/keys or SoftCam.Key cleanup.
cam_restore_config() {
    CR_KIND=$1
    CR_BACKUP=$2
    [ -d "$CR_BACKUP/tuxbox-config" ] || return 0
    mkdir -p /etc/tuxbox/config || return 1
    for CF in "$CR_BACKUP/tuxbox-config/$CR_KIND".* "$CR_BACKUP/tuxbox-config/$CR_KIND"; do
        [ -e "$CF" ] || [ -L "$CF" ] || continue
        BASE_NAME=${CF##*/}
        if [ ! -e "/etc/tuxbox/config/$BASE_NAME" ] && [ ! -L "/etc/tuxbox/config/$BASE_NAME" ]; then
            cp -a "$CF" /etc/tuxbox/config/ || return 1
        fi
    done
    return 0
}

cam_cleanup_config() {
    CC_KIND=$1
    for CF in "/etc/tuxbox/config/$CC_KIND".* "/etc/tuxbox/config/$CC_KIND"; do
        [ -e "$CF" ] || [ -L "$CF" ] || continue
        # Exact prefixes only; NEVER remove the shared config directory.
        rm -rf "$CF" || return 1
    done
    return 0
}

# Remove only binaries that bit-for-bit match those included in the uploaded
# IPKs. These files are copied by vendor postinst, so opkg alone can leave them.
# Never delete a binary that has been replaced/modified externally.
cam_cleanup_programs() {
    CP_KIND=$1
    CP_BACKUP=$2
    CP_CHECK=0
    case "$CP_KIND" in
        ncam)
            CP_ALLOWED='5d6217bbcbf97dcf7accd604a269182d1ece2596d6b54a232d6fc1805f57b054 5ff66c11f8e1ae4dba2f1f7e9b03b5cfc185616941fc07d52d2e017f9d7c9b89 a91565f841f616e3f82397e800f1a8cd1baa995a2207d8a30ec2b71014f069d8 fecb273d33ba8d8f20c7fc6a30af5c6d7b6eb649812749a30459ad78446e676d'
            CP_FILES='/usr/bin/ncam-15.8 /usr/bin/ncam'
            CP_SCRIPT='/etc/init.d/softcam.ncam-15.8'
            ;;
        oscam)
            CP_ALLOWED='2848e9f36f3c6bef3e4d84e382a248c3a4b09cdb78f4bbd84151f26bc9629aa8 3c90616a62536d6c9cad7dcad94617f8b2eba195e4a4a54db50c35a52c174b93 54abbd47d529c0e0f7dce25ddc524ab85afd1e3e85c285baccdb2e40ecb41aea 6f6edb033acb48d7f1194ca6fa9167c8582d327ab37acdae44310baa7340b086 79b9da3a029fcd09781396eb2015db502d5d824c17312b2a559e6797eb2bb7cc 9d93d302a675a6f6d974fcce464c7de36dd6c7793bcafba14b9f921940a187a4 a5c6d00c888e6597b7b8e51e176ee5de320b1f021e121b7c6edc569440bed4b1 a671d38964a2db7a55418067324d356451d02a03d8a5846652c4b26170b38906 ad7905f7c0a1e14ed5432beefae8738c626ba31743da05c3607b003f1b0b66d0 c250b0f387f07653e73a1eacbc97af7c129ccc2f9101e31548910ba40f72e5be cf0345e74ec3b0b6eb39d7864193726642965eca978c33846b459aae0c7154fe d6d715c700cfb2014323c84f6388f71dee1586ce72d926065acc3d0cdca56d4d e2113380a1cc70c79d7dcd3579bcbb2cc53edb64a455eeeaeb0b8ac73b9133bb f6ec86e5bb0b1d907bf2023f8f57e8fd56db48e42b3991467f96fba1d2afe8b6 f7c66d673bf80c0a6e59c509fa7bcd783db4d032332acff6a79f7646cdd4738e'
            CP_FILES='/usr/bin/oscam /usr/bin/OSCam_11968-803'
            CP_SCRIPT='/etc/init.d/softcam.OSCam_11968-803'
            ;;
        *) return 2 ;;
    esac
    for CP_FILE in $CP_FILES; do
        [ -e "$CP_FILE" ] || [ -L "$CP_FILE" ] || continue
        if [ ! -f "$CP_FILE" ] || [ -L "$CP_FILE" ]; then
            report "CHECK: unexpected $CP_FILE; left in place."
            CP_CHECK=1
            continue
        fi
        CP_SHA=$(sha256sum "$CP_FILE" 2>/dev/null | awk '{print $1}')
        case " $CP_ALLOWED " in
            *" $CP_SHA "*)
                cp -p "$CP_FILE" "$CP_BACKUP/${CP_FILE##*/}" || return 2
                rm -f "$CP_FILE" || return 2
                report "Removed verified binary: $CP_FILE"
                ;;
            *)
                report "CHECK: binary $CP_FILE does not match supplied IPK; preserved."
                CP_CHECK=1
                ;;
        esac
    done
    # Version-specific launcher files may be removed, never generic softcam scripts.
    if [ -f "$CP_SCRIPT" ] && [ ! -L "$CP_SCRIPT" ]; then
        cp -p "$CP_SCRIPT" "$CP_BACKUP/${CP_SCRIPT##*/}" || return 2
        rm -f "$CP_SCRIPT" || return 2
    fi
    [ "$CP_CHECK" -eq 0 ] || return 2
    return 0
}

remove_verified_cam() {
    CAM_KIND=$1
    case "$CAM_KIND" in
        ncam)
            CAM_PKG=enigma2-plugin-softcams-ncam
            CAM_SUM=c0e520381bc9ca14c3a82c979134f810640011e6ddeb638f467495c6b4d00e06
            ;;
        oscam)
            CAM_PKG=enigma2-plugin-softcams-oscam-emu-pcsc-levi45
            CAM_SUM=fc34abcbf73f1c42e653e4111ec2b39ac2f9f4e3b73943c38c14d6a534262f7d
            ;;
        *) return 2 ;;
    esac
    if ! pkg_installed "$CAM_PKG"; then
        report "CHECK: $CAM_KIND package not registered with opkg; manual install cannot be removed safely."
        return 2
    fi
    INFO_DIR=/var/lib/opkg/info
    [ -d "$INFO_DIR" ] || INFO_DIR=/usr/lib/opkg/info
    CAM_POSTRM="$INFO_DIR/$CAM_PKG.postrm"
    CAM_PRERM="$INFO_DIR/$CAM_PKG.prerm"
    if [ -e "$CAM_PRERM" ] || [ -L "$CAM_PRERM" ]; then
        report "CHECK: unexpected $CAM_KIND prerm; no removal attempted."
        return 2
    fi
    if [ ! -f "$CAM_POSTRM" ] || [ -L "$CAM_POSTRM" ] || ! command -v sha256sum >/dev/null 2>&1; then
        report "CHECK: $CAM_KIND removal script cannot be verified; no removal attempted."
        return 2
    fi
    ACTUAL_SUM=$(sha256sum "$CAM_POSTRM" 2>/dev/null | awk '{print $1}')
    if [ "$ACTUAL_SUM" != "$CAM_SUM" ]; then
        report "CHECK: different $CAM_KIND postrm installed; no removal attempted."
        return 2
    fi
    umask 077
    CAM_BACKUP="/home/root/apanel-backups/${CAM_KIND}-$(date +%Y%m%d-%H%M%S)-$$"
    mkdir -p "$CAM_BACKUP" || return 1
    chmod 700 "$CAM_BACKUP" || return 1
    cp -p "$CAM_POSTRM" "$CAM_BACKUP/postrm.original" || return 1
    if [ -d /etc/tuxbox/config ]; then
        cp -a /etc/tuxbox/config "$CAM_BACKUP/tuxbox-config" || {
            report 'CHECK: config backup failed; package was not touched.'
            return 2
        }
    fi
    # A harmless postrm replaces the upstream wildcard-deleting script.
    if ! printf '#!/bin/sh\nexit 0\n' > "$CAM_POSTRM" || ! chmod 755 "$CAM_POSTRM"; then
        cp -p "$CAM_BACKUP/postrm.original" "$CAM_POSTRM" 2>/dev/null || true
        report 'CHECK: cannot guard package postrm; no removal attempted.'
        return 2
    fi
    opkg remove "$CAM_PKG"
    CAM_RC=$?
    if [ "$CAM_RC" -ne 0 ] || pkg_installed "$CAM_PKG"; then
        if pkg_installed "$CAM_PKG"; then
            cp -p "$CAM_BACKUP/postrm.original" "$CAM_POSTRM" 2>/dev/null || true
        fi
        report "FAILED: $CAM_KIND opkg removal unsuccessful. Backup: $CAM_BACKUP"
        return 1
    fi
    CAM_PROGRAM_RESULT=0
    cam_cleanup_programs "$CAM_KIND" "$CAM_BACKUP" || CAM_PROGRAM_RESULT=2
    case "$CAM_REMOVE_MODE" in
        clean)
            if ! cam_cleanup_config "$CAM_KIND"; then
                report "CHECK: $CAM_KIND removed but some settings remain. Backup: $CAM_BACKUP"
                return 2
            fi
            report "$CAM_KIND removed with cam-specific settings; shared keys preserved. Backup: $CAM_BACKUP"
            ;;
        *)
            if ! cam_restore_config "$CAM_KIND" "$CAM_BACKUP"; then
                report "CHECK: $CAM_KIND removed but some settings could not be restored. Backup: $CAM_BACKUP"
                return 2
            fi
            report "$CAM_KIND removed; settings retained. Backup: $CAM_BACKUP"
            ;;
    esac
    [ "$CAM_PROGRAM_RESULT" -eq 0 ] || {
        report "CHECK: package removed, but unverified program files remain. Backup: $CAM_BACKUP"
        return 2
    }
    return 0
}

remove_plugin_key() {
    # Only verified package names may be removed; EMUs use a guarded postrm.
    case "$1" in
        mystreamer)
            if pkg_installed enigma2-plugin-extensions-mystreamer; then
                opkg_remove_pkg enigma2-plugin-extensions-mystreamer || return 1
                report 'MyStreamer package removed. Personal settings kept.'
                return 0
            fi
            report 'CHECK: MyStreamer package not found; no files removed.'
            return 2
            ;;
        furybiss)
            FOUND=0
            for P in enigma2-plugin-extensions-furybiss enigma2-plugin-extensions-furybis; do
                if pkg_installed "$P"; then
                    FOUND=1
                    opkg_remove_pkg "$P" || return 1
                fi
            done
            [ "$FOUND" -eq 1 ] || {
                report 'CHECK: FuryBiss package not found; no files removed.'
                return 2
            }
            report 'FuryBiss package removed. Personal settings kept.'
            return 0
            ;;
        ipaudioplus)
            report 'CHECK: IPAudio Plus uninstall not yet verified against its IPK removal scripts; no files removed.'
            return 2
            ;;
        xstreamity)
            if pkg_installed enigma2-plugin-extensions-xstreamity; then
                opkg_remove_pkg enigma2-plugin-extensions-xstreamity || return 1
                report 'XStreamity package removed. Playlists/settings kept.'
                return 0
            fi
            report 'CHECK: XStreamity package not found; no files removed.'
            return 2
            ;;
        ncam)
            remove_verified_cam ncam
            ;;
        oscamlevi)
            remove_verified_cam oscam
            ;;
        *)
            report "CHECK: uninstall mapping for $1 not verified; no files removed."
            return 2
            ;;
    esac
}

run_mode() {
    MODE=$1
    [ -r "$CHOICES" ] || {
        say 'No plugin selection.'
        return 1
    }

    SELECTED=$(tr '\n' ' ' < "$CHOICES")
    COUNT=$(count_words "$SELECTED")
    TOTAL=$((COUNT + 1))
    NUM=0
    DONE=0
    OK=0
    CHECK=0
    FAIL=0

    : > "$PROGRESS"
    echo "$MODE" > "$MODEFILE"
    CAM_REMOVE_MODE=keep
    if [ "$MODE" = remove ] && [ -r "$REMOVE_OPTIONS" ]; then
        read -r CAM_REMOVE_MODE < "$REMOVE_OPTIONS"
        case "$CAM_REMOVE_MODE" in
            keep|clean) : ;;
            *) CAM_REMOVE_MODE=keep ;;
        esac
    fi

    if [ "$MODE" = install ]; then
        if ! begin_restart_guard; then
            end_restart_guard
            report 'FAILED: restart deferral could not be prepared; installation not started.'
            rm -f "$PIDFILE"
            return 1
        fi
        report "A Panel $VERSION | Install mode | $TOTAL steps"
        step 'Update OpenATV feed' opkg update
        # Display order is alphabetic; install order is deliberate.
        # AJ Panel is first. MixAudio, NCam and OSCam are the last three.
        # Child installer restart commands are deferred until the final reboot.
        for K in aj subs transmission tmdb arabicsavior raed audioshift ipaudioplus ipaudio customcs aglare livefeed epggrabber xstreamity mystreamer moviesostende furybiss mixaudio ncam oscamlevi; do
            case " $SELECTED " in
                *" $K "*) : ;;
                *) continue ;;
            esac
            NAME=$(plugin_name "$K")
            [ -n "$NAME" ] || continue
            step "$NAME" install_plugin_key "$K"
        done
        report '=== INSTALL FINISHED ==='
        report 'Full receiver reboot in 5 seconds.'
    else
        report "A Panel $VERSION | Uninstall mode | $TOTAL steps"
        step 'Refresh package status' true
        for K in $SELECTED; do
            NAME=$(plugin_name "$K")
            [ -n "$NAME" ] || continue
            step "Remove $NAME" remove_plugin_key "$K"
        done
        report '=== UNINSTALL PASS COMPLETE (CHECK means skipped) ==='
        report 'Restarting Enigma2 in 5 seconds (verified removals only).'
    fi

    bar
    report "Results: OK=$OK CHECK=$CHECK FAILED=$FAIL"
    report "Full log: $LOG"

    sync
    sleep 5
    rm -f "$PIDFILE"
    if [ "$MODE" = install ]; then
        # Restore real commands before issuing our single final receiver reboot.
        end_restart_guard
        reboot
    else
        init 4
        sleep 3
        init 3
    fi
}

plugin_name() {
    case "$1" in
        aj) echo 'AJ Panel' ;;
        subs) echo 'SubsSupport Pro' ;;
        transmission) echo 'Transmission' ;;
        tmdb) echo 'TMDB' ;;
        arabicsavior) echo 'Arabic Savior' ;;
        raed) echo 'Raed Quick Signal' ;;
        audioshift) echo 'AudioShift (Dreambox One only)' ;;
        ipaudio) echo 'IPAudio Pro' ;;
        ipaudioplus) echo 'IPAudio Plus' ;;
        customcs) echo 'Custom Channel Selection' ;;
        aglare) echo 'Aglare Skin' ;;
        livefeed) echo 'LiveFeed' ;;
        epggrabber) echo 'EPG Grabber' ;;
        xstreamity) echo 'XStreamity (OpenATV feed)' ;;
        mixaudio) echo 'MixAudio' ;;
        ncam) echo 'NCam' ;;
        oscamlevi) echo 'OSCam' ;;
        mystreamer) echo 'MyStreamer' ;;
        furybiss) echo 'FuryBiss' ;;
        moviesostende) echo 'Movies & Series Ostende' ;;
        *) echo '' ;;
    esac
}

if [ "${1:-}" = '--run-install' ]; then
    [ "$(id -u)" -eq 0 ] && command -v opkg >/dev/null 2>&1 || exit 1
    run_mode install
    exit $?
fi

if [ "${1:-}" = '--run-remove' ]; then
    [ "$(id -u)" -eq 0 ] && command -v opkg >/dev/null 2>&1 || exit 1
    run_mode remove
    exit $?
fi

if [ "$(id -u)" -ne 0 ] || ! command -v opkg >/dev/null 2>&1; then
    say 'ERROR: Root and OpenATV/opkg required'
    exit 1
fi

if ! command -v python3 >/dev/null 2>&1; then
    say 'ERROR: Python3 required'
    exit 1
fi

# Open the menu without restarting an already loaded GUI.
if [ -r "$READY" ]; then
    read -r UI_VERSION UI_PID < "$READY"
    if [ "$UI_VERSION" = "$VERSION" ] && [ -n "$UI_PID" ] && kill -0 "$UI_PID" 2>/dev/null; then
        : > "$REQUEST"
        say "A Panel $VERSION: opening the TV menu now."
        exit 0
    fi
fi

# New installation or GUI plugin update.
mkdir -p "$ROOT" "$PLUG" || exit 1
cp "$0" "$CORE" || exit 1
chmod 755 "$CORE"

