"""
try:
    data = base64.b64decode(payload)
    zf = zipfile.ZipFile(io.BytesIO(data))
    for name in zf.namelist():
        # An explicit allowlist prevents accidental path traversal.
        if not (name.startswith('icons/') and name.endswith('.png') or name in ('background_1280.png', 'background_1920.png', 'plugin.png', 'tick.png', 'controls/trash.png', 'controls/refresh.png')):
            raise ValueError('Unexpected asset: ' + name)
        target = os.path.join(root, name)
        folder = os.path.dirname(target)
        if not os.path.isdir(folder):
            os.makedirs(folder)
        with open(target, 'wb') as f:
            f.write(zf.read(name))
    zf.close()
    icon = os.path.join(root, 'plugin.png')
    main_icon = os.path.join(sys.argv[1], 'plugin.png')
    with open(icon, 'rb') as inp:
        with open(main_icon, 'wb') as out:
            out.write(inp.read())
    print('A Panel assets ready: 20 plugin icons, two UI control icons, backgrounds, and plugin.png')
except Exception as e:
    print('ERROR: asset unpack failed:', e)
    sys.exit(1)
APANEL_ASSETS
if [ "$?" -ne 0 ]; then
    say 'ERROR: Visual asset extraction failed. No GUI restart will be triggered.'
    exit 1
fi

